1	import { cmdImport, cmdReadings, CSV_HEADER } from './src/commands.ts';
2	import { cmdDaily } from './src/report.ts';
3	import { cmdAck, cmdAlerts, cmdEvaluate, cmdRuleCreate, cmdRuleList } from './src/alerts.ts';
4	import { cmdGroupConfigure, cmdGroupDaily, cmdGroupHistory } from './src/groups.ts';
5	import { cmdCorrect, cmdCorrections, cmdUndo } from './src/correct.ts';
6	import { cmdBackup, cmdRestore, withDirectoryCoordination } from './src/backup.ts';
7	import { parseIso8601, parseUtcDate } from './src/time.ts';
8	import { canonicalTimezone, loadTimezone } from './src/tz.ts';
9	import { parseKwh } from './src/value.ts';
10	import type { CorrectionItem } from './src/store.ts';
11	
12	const name = 'meterwatch';
13	
14	const help = `${name}
15	
16	建筑能耗监测:本地累计电表读数导入与消耗核查。
17	
18	Usage:
19	  node app.ts                       显示本帮助
20	  node app.ts --help | -h           显示本帮助
21	  node app.ts import <file.csv>     导入 CSV 读数(整批成功或整批拒绝)
22	  node app.ts readings [筛选...]    查询读数、区间与消耗
23	  node app.ts daily --from <iso> --to <iso> [--device <id>...] [--tz <时区>] [--max-interval <秒>]
24	                                    按当地自然日核查能耗的只读日报(默认 UTC 分日)
25	  node app.ts rule create --id <id> (--device <设备> | --group <分组>) --threshold <kWh> [--tz <时区>] [--max-interval <秒>]
26	                                    创建每日能耗阈值告警规则(设备或分组,时区省略为 UTC)
27	  node app.ts rule list             查看全部告警规则
28	  node app.ts evaluate --rule <id> --from <日期> --to <日期>
29	                                    评估规则在连续完整当地日期(按规则时区)上的超限情况
30	  node app.ts alerts --rule <id> [--from <日期> --to <日期>]
31	                                    查询规则的告警历史(只读)
32	  node app.ts ack <告警标识>         确认告警
33	  node app.ts group configure --id <id> --at <iso> --device <id>...
34	                                    配置分组成员版本(首次配置即建立分组)
35	  node app.ts group history --id <id>
36	                                    查看分组成员版本历史(只读)
37	  node app.ts group daily --id <id> --from <iso> --to <iso> [--tz <时区>] [--max-interval <秒>]
38	                                    按当时生效成员的分组能耗日报(只读,默认 UTC 分日)
39	  node app.ts correct --request <id> --item --device <设备> --at <iso> --expect <kWh> --set <kWh>
40	                                    [--item --device ... --at ... --expect ... --set ...]...
41	                                    批量修正已存读数的累计值(整批成功或整批拒绝)
42	  node app.ts undo --request <id> --target <修正请求标识>
43	                                    整批撤销一次已成功修正(恢复实际改变过的读数)
44	  node app.ts corrections             查看修正与撤销历史(只读)
45	  node app.ts backup <快照文件>       导出全库快照(快照文件须位于数据目录之外,已存在则拒绝)
46	  node app.ts restore <快照文件>      从快照整库恢复(三个业务存储作为一次提交整体替换)
47	
48	备份与恢复(backup / restore):
49	  backup 把当前数据目录的三个业务存储(读数与修正/撤销历史、告警规则与历史、
50	  分组成员版本)连同后续编号状态完整导出为一个快照文件,任意大数精确保留;
51	  快照带格式版本与 SHA-256 完整性校验。快照文件必须位于数据目录之外,已存在
52	  的输出文件拒绝覆盖;备份只读取业务数据,不改写。restore 不解析当前库(可用于
53	  当前存储已损坏的目录),先校验快照的版本、完整性与三个存储的结构和关联
54	  (全库重复读数身份、修正项引用缺失读数、撤销引用缺失修正、成员或规则目标
55	  不存在、告警引用缺失规则,任一问题指出原因并拒绝),再把三个业务存储作为
56	  一次提交整体替换:成功后业务状态完全等于快照,快照为空的部分清除原数据,
57	  快照之后新增的读数、请求和告警不保留,目录内其他文件保持不变,不自动评估
58	  或重新生成历史。读写或重命名失败返回 1 并回退到恢复前文件内容与存在状态。
59	
60	进程在准备、文件替换、失败回滚或启动自恢复中被终止的处理:
61	  任一命令(含无参数、--help/-h 与非法参数入口)再次启动,都先取得数据目录
62	  操作权并续接未完成恢复,然后才执行查询或写入。恢复日志用阶段记录进度:
63	  尚未进入失败回滚的中断可收敛为完整旧库或完整快照;已经进入失败回滚后
64	  只能继续还原完整旧库,不能改为前滚;自恢复再次中断仍可续接。回滚中已
65	  还原的旧文件不会被误删,原本缺失的业务文件恢复为缺失(不把事务造成的
66	  缺文件当成空库)。无法可靠判定或完成一致恢复时返回 1:不输出正常业务
67	  结果、不做业务写入,也不删除仍可用于恢复的材料(restore.journal 与
68	  *.restore-old / *.restore-new),修好底层读写问题后再运行任一命令即可续接。
69	
70	目录操作权(排他锁,按数据目录隔离):
71	  每个命令从取得目录操作权起先协调再读写。同目录被其他存活进程占用时
72	  明确拒绝并返回 1,不读写业务存储,也不清理对方的事务材料;属主退出后
73	  可安全接管其未完成恢复;不同数据目录互不阻塞。备份、恢复与启动自恢复
74	  期间,其他命令同样受此限制。锁文件为数据目录内的 meterwatch.lock。
75	
76	故障处理简述:
77	  - 命令报 "locked by another live meterwatch process":等占用进程结束,
78	    或确认其已退出后删除残留的 meterwatch.lock 再重试。
79	  - 报 "cannot complete interrupted restore ... materials were kept":
80	    保留目录内 restore.journal 与 *.restore-old/*.restore-new,排除磁盘
81	    只读/权限/空间问题后,再运行任意命令完成续接;切勿手工删改这些文件。
82	  - 报 restore journal 不可读或无效:目录处于无法自动判定的状态,需用已知
83	    完好的快照手工恢复,不要直接在可能混合的目录上继续业务操作。
84	
85	筛选(readings):
86	  --device <id>     只显示指定设备(可重复使用,区分大小写)
87	  --from <iso8601>  起始时刻(含),如 2026-01-01T00:00:00Z
88	  --to <iso8601>    结束时刻(不含)
89	  省略边界表示不限;时间必须为秒精度 ISO8601 且带 Z 或数字时区偏移
90	  (如 +08:00);起点不早于终点时拒绝查询。
91	
92	日报(daily):
93	  --from <iso8601>  起始时刻(含),必填
94	  --to <iso8601>    结束时刻(不含),必填,必须晚于起点
95	  --device <id>     只统计指定设备(可重复使用);省略时统计库内全部设备
96	  --tz <时区>       分日时区(IANA 名,如 Asia/Shanghai);省略时按 UTC
97	  --max-interval <秒>  最大采样间隔限制(正整数秒);省略表示无上限,只影响本次查询
98	  日期按分日时区的当地零点划分,首尾日期只统计与查询范围重叠的部分。
99	  估算口径:由每个设备完整时序的相邻读数构成区间,区间两端读数即使在
100	  查询范围外也参与;非下降区间把累计值之差按持续时间均匀分摊,以千分之一
101	  kWh 为单位,从区间起点累计到切点(查询边界与日界线)向下取整,片段消耗
102	  为两端累计量之差,故完整区间的分摊总量等于原差值,同一区间拆开查询再
103	  相加结果一致。下降区间不分摊,记为异常覆盖;首条读数之前、末条之后及
104	  孤立读数时段为未知,不外推。采用 --max-interval 时,非下降相邻区间的
105	  实际时间差超过限制即把整个区间记为未知(等于限制仍可信;下降区间即使
106	  超过限制仍为异常),不因查询范围或日界线裁短而变成可信区间。每天输出
107	  估算消耗与有效/异常/未知覆盖秒数(三者之和等于该天实际统计的各 UTC
108	  时段总秒数),并标明所用时区、采用的间隔限制与各 UTC 时段;采用限制时
109	  另显示过长间隔造成的未知秒数(gap)及相关设备与原始相邻读数时刻;
110	  存在未知或异常覆盖时日报标记为不完整。日报只读,不写入数据。
111	
112	分日时区(--tz,daily 与 group daily 可选):
113	  接受运行环境支持的 IANA 时区名(如 Asia/Shanghai、America/New_York);
114	  未知时区名为参数错误,返回 2。时区只决定分日,不重新解释输入时刻或
115	  已存读数。日界线按实际时刻的当地日期归属计算,不按固定 86400 秒或
116	  全年固定偏移推算:夏令时前拨跳过的当天更短(跳过的小时不存在,不补
117	  为未知),回拨当天更长(重复小时按各自实际时刻完整计入);同一当地
118	  日期的不连续时段合并统计、分别列出;没有实际时段的当地日期不生成
119	  日报。日界线不重置分摊起点,拆开查询再相加与整段一致。
120	
121	分组(group configure / history / daily):
122	  分组以首次 configure 建立,标识非空唯一(去首尾空白、区分大小写)。
123	  configure 的 --at 为版本生效时刻(含,秒精度 ISO8601 带 Z 或数字时区
124	  偏移),--device 给出一整套已有设备(至少一个,可重复;同设备重复列出
125	  只算一次,成员顺序不影响等价性,设备可属于多个分组);版本从生效时刻起
126	  生效直到下一版本接替,允许乱序补录历史版本。同组同一实际生效时刻、同
127	  成员集合重试成功且不新增,异成员集合报冲突;未知设备报错,配置整次成功
128	  或不提交。history 按生效时刻列出全部版本(只读)。daily 的 --from(含)
129	  与 --to(不含)必填且起点必须更早,按分日时区的自然日切分(--tz 可选,
130	  默认 UTC,口径见上文"分日时区"),按当时生效成员计算,首个版本生效前
131	  记为未知;每个时段只有全部生效成员均处于非下降读数
132	  区间才是有效覆盖并计入成员消耗之和,任一成员下降为异常,否则任一成员
133	  未知为未知;异常与未知时段不计任何成员消耗,覆盖秒数按分组实际时间计;
134	  各设备片段仍以原读数区间起点累计比例向下取整,日界线、查询边界与成员
135	  切换均不重置分摊起点,拆开查询相加一致。daily 接受可选 --max-interval
136	  <秒>(正整数,省略为无上限,只影响本次查询):成员的非下降相邻区间实际
137	  时间差超过限制即把整个区间记为未知(等于限制仍可信;下降区间仍为异常,
138	  不因查询范围、日界线或成员切换裁短);分组的过长间隔未知秒数(gap)只在
139	  最终未知时段内按实际时间计并集,不叠加成员秒数。每天显示生效成员及其
140	  时段、估算消耗与有效/异常/未知秒数(三者之和等于当天查询时长),采用
141	  限制时另显示 gap 秒数及相关设备与原始相邻读数时刻;有异常或未知标为
142	  不完整,无有效覆盖显示无法计算。配置不改读数、规则和告警,导入不改配置。
143	
144	修正与撤销(correct / undo / corrections):
145	  correct 一次提交指定非空请求标识(--request,去首尾空白、区分大小写,在
146	  数据目录内唯一)及至少一个 --item 修正项;每项 --device、--at、--expect、
147	  --set 各恰好一个,给出设备、实际时刻(秒精度 ISO8601 带 Z 或数字时区
148	  偏移)、预期原读数和替换读数(均为非负、最多三位小数 kWh,任意大数精确)。
149	  只修改已有读数的累计值,不新增或删除读数;同批同一读数身份(设备+实际
150	  时刻)只允许一项;替换值可等于原值,但仍须核验预期原值。首次提交逐项把
151	  预期原值与操作前已存值精确比较,全部匹配才整体替换,成功报告请求标识与
152	  实际改变数;任一项身份不存在或原值不符均指出原因、整批拒绝,不改变其他
153	  项,也不占用请求标识(失败后可修改内容用同一标识重新提交)。读数替换与
154	  请求成功记录同时持久化,写入失败保留操作前全部状态。同标识、同修正内容
155	  重放直接返回原成功结果,不重新校验当前读数、不再次替换(即使这些读数
156	  后来又被其他请求修正,或本修正后来被撤销);修正项顺序、等价时区及等价
157	  十进制写法不影响内容等价性;同标识异内容报冲突且保持状态。
158	  undo 一次提交指定非空撤销请求标识(--request)及目标修正请求标识
159	  (--target),整批撤销一次已成功修正,不允许挑选部分项;目标只能是成功
160	  修正,不能是撤销请求,未知或已撤销目标报错。撤销与修正请求共用唯一标识
161	  空间,成功标识绑定操作类型和内容。首次撤销只恢复目标中实际改变过的读数,
162	  将其还原为该修正记录的原值,不新增或删除读数;每个待恢复身份必须存在、
163	  当前值精确等于原替换值,且没有后来尚未撤销、实际改变过该读数的修正
164	  (后来改回相同数值也不能绕过来源检查,相关后续修正先撤销后才能再撤销
165	  较早请求)。同值项不恢复、不阻塞;全部为同值项的目标仍可成功撤销,恢复
166	  数为零。任一项不满足条件指出身份和原因、整次拒绝,不占用撤销标识。同
167	  撤销标识、同目标重放返回原成功结果,不重新核验、不重复恢复;同标识异
168	  目标或跨操作类型复用标识均报冲突。读数恢复与撤销成功记录同时原子持久化,
169	  重启后状态与来源判断一致。成功报告撤销请求、目标和恢复数,原修正内容
170	  保留并标记已撤销。corrections 按成功提交顺序显示各修正请求及各项设备、
171	  时刻、原值和替换值,另按成功发生顺序显示撤销请求与目标关系,只读。
172	  修正与撤销后 readings、daily、group daily 与 alerts 的当前消耗按新相邻
173	  区间重算;分组成员、规则与告警记录不变,检测状态仍需显式 evaluate 更新;
174	  后续 import 按当前读数判重与冲突,并保留修正与撤销历史。
175	
176	告警规则(rule / evaluate / alerts / ack):
177	  规则标识非空且在设备与分组两类规则间唯一(去首尾空白、区分大小写);用
178	  --device 绑定一个已有存储读数的设备,或用 --group 绑定一个已有分组(二者
179	  恰好其一);设备与分组即使同名也是不同目标,列表与历史均显示目标类型。
180	  阈值非负、最多三位小数 kWh;目标、阈值、时区与采样间隔限制创建后固定,
181	  分组规则绑定分组标识、不冻结创建时成员。--tz 可选,接受运行环境支持的
182	  IANA 时区名(如 Asia/Shanghai、America/New_York),省略为 UTC(与显式
183	  UTC 等价);时区按运行环境解析后的规范名存储与比较,未知时区名为参数
184	  错误,返回 2。--max-interval 可选,为正整数秒数的最大采样间隔限制,
185	  省略为无上限:非下降相邻区间的实际时间差超过限制即把整个区间记为未知
186	  (等于限制仍可信;下降区间即使超过限制仍为异常),仅全天有效覆盖的
187	  日期才与阈值比较。相同标识、同目标类型、同目标标识、等价阈值、同时区
188	  及同间隔限制重试成功且不重复创建,任一不同即报冲突。规则限制与列表
189	  显示重启后保留,备份恢复完整保留;旧规则与旧快照未设置限制时按无上限
190	  使用,已存非法限制按损坏数据拒绝。
191	  evaluate 与 alerts 的 --from/--to 为 YYYY-MM-DD 的当地日期(按规则时区
192	  解释),起日含、止日不含,起日必须更早。每个日期统计归属该日期的全部实际
193	  UTC 时段,不把当地午夜套用固定偏移:夏令时短日不补未知,回拨重复小时完整
194	  计入,日期回退的不连续时段合并为同一天、一次评估只作一次判定;整日被跳过
195	  的日期标明跳过,不判定、不创建也不恢复告警。设备规则评估口径与 daily 相同;
196	  分组规则与 group daily 的联合覆盖口径相同:每天按当时生效的成员版本计算,
197	  允许日内切换,首个版本生效前为未知,任一成员下降为异常,否则任一成员未知
198	  为未知;成员切换不重置各设备原读数区间的分摊起点。仅全天有效覆盖的日期
199	  可判定,消耗严格大于阈值才超限(等于为正常),零增长有效;有未知或下降
200	  覆盖的日期不可判定,不触发也不恢复。每个规则每个日期独立跟踪:首次超限
201	  创建带全局唯一标识的未确认告警,重复超限保留原标识;完整评估正常才记录
202	  恢复;恢复后再超限创建新的未确认告警,旧记录保留,原确认不转移。批量日期
203	  评估要么全部提交要么不提交。
204	  ack 按告警标识确认,已恢复告警也可确认;重复确认成功且不重复记事,确认
205	  不改变超限或恢复状态。alerts 按规则和当地日期升序展示当前计算的消耗或不
206	  可判定原因、实际 UTC 时段及有效/异常/未知秒数(采用间隔限制时另显示过长
207	  间隔造成的未知秒数及相关设备与原始相邻读数时刻)、各次告警的标识、检测状态、
208	  确认状态及按发生顺序排列的触发/恢复/确认事件(触发、恢复时的消耗为当时
209	  记录,不随后续数据改写);省略日期范围时展示有告警记录的全部日期;查询
210	  只读,不会隐式恢复。导入读数或补录成员版本都不自动评估,需显式重评才更新
211	  检测状态。规则时区、间隔限制与历史重启后保留;没有时区的旧规则按 UTC 使用,
212	  未设置间隔限制的旧规则与旧快照按无上限使用,原告警标识、日期、状态和事件
213	  顺序保留。
