262	/** 解析 --device/--from/--to(及允许时的 --tz、--max-interval)选项;出错返回错误消息字符串。 */
263	function parseOptions(rest: string[], allowTz = false, allowMaxInterval = false): ParsedOptions | string {
264	  const devices: string[] = [];
265	  let from: number | undefined;
266	  let to: number | undefined;
267	  let tz: string | undefined;
268	  let maxInterval: number | undefined;
269	  for (let i = 0; i < rest.length; i++) {
270	    let opt = rest[i];
271	    let value: string | undefined;
272	    const eq = opt.indexOf('=');
273	    if (opt.startsWith('--') && eq !== -1) {
274	      value = opt.slice(eq + 1);
275	      opt = opt.slice(0, eq);
276	    } else if (opt.startsWith('--')) {
277	      value = rest[i + 1];
278	      if (value === undefined) return `选项 '${opt}' 缺少值`;
279	      i++;
280	    } else {
281	      return `无法识别的参数 '${opt}'`;
282	    }
283	    if (opt === '--device') {
284	      if (value.trim() === '') return "'--device' 的值不能为空";
285	      devices.push(value);
286	    } else if (opt === '--from' || opt === '--to') {
287	      const ts = parseIso8601(value.trim());
288	      if (ts === null) {
289	        return `选项 '${opt}' 的时间无效: '${value}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
290	      }
291	      if (opt === '--from') from = ts;
292	      else to = ts;
293	    } else if (opt === '--tz' && allowTz) {
294	      tz = value.trim();
295	      if (tz === '') return "'--tz' 的值不能为空";
296	    } else if (opt === '--max-interval' && allowMaxInterval) {
297	      const n = parseMaxInterval(value);
298	      if (n === null) {
299	        return `选项 '--max-interval' 的值无效: '${value.trim()}'(需正整数秒数)`;
300	      }
301	      maxInterval = n;
302	    } else {
303	      return `无法识别的选项 '${opt}'`;
304	    }
305	  }
306	  return { devices, from, to, tz, maxInterval };
307	}
