309	/** 校验 IANA 分日时区名;无效时返回错误消息字符串。 */
310	function checkTz(tz: string): string | null {
311	  if (loadTimezone(tz) === null) {
312	    return `未知时区 '${tz}'(需运行环境支持的 IANA 时区名,如 Asia/Shanghai、America/New_York)`;
313	  }
314	  return null;
315	}
