342	/** 取恰好出现一次的单值选项;缺失或重复返回 null。 */
343	function oneFlag(flags: Map<string, string[]>, name: string): string | null {
344	  const list = flags.get(name);
345	  if (!list || list.length !== 1) return null;
346	  return list[0];
347	}
