349	/** 解析 YYYY-MM-DD 日期选项为当地日期标签;无效时返回错误消息字符串。 */
350	function dateFlag(value: string, label: string): { date: string } | string {
351	  const v = value.trim();
352	  if (parseUtcDate(v) === null) {
353	    return `${label}无效: '${v}'(需 YYYY-MM-DD 的真实日期)`;
354	  }
355	  return { date: v };
356	}
