430	function cmdEvaluateEntry(rest: string[]): number {
431	  const flags = parseFlags(rest, ['--rule', '--from', '--to']);
432	  if (typeof flags === 'string') return usageError(flags);
433	  const ruleRaw = oneFlag(flags, '--rule');
434	  const fromRaw = oneFlag(flags, '--from');
435	  const toRaw = oneFlag(flags, '--to');
436	  if (ruleRaw === null || fromRaw === null || toRaw === null) {
437	    return usageError("'evaluate' 需要 --rule、--from、--to 各恰好一个(日期为 YYYY-MM-DD,起日含、止日不含)");
