439	  const ruleId = ruleRaw.trim();
440	  if (ruleId === '') return usageError('规则标识不能为空');
441	  const from = dateFlag(fromRaw, '起始日期');
442	  if (typeof from === 'string') return usageError(from);
443	  const to = dateFlag(toRaw, '结束日期');
444	  if (typeof to === 'string') return usageError(to);
445	  if (from.date >= to.date) return usageError('评估起日必须早于止日(--from < --to)');
446	  return cmdEvaluate({ ruleId, from: from.date, to: to.date });
447	}
