568	/**
569	 * 解析 correct 的修正项:以裸 '--item' 分段,每段需 --device/--at/--expect/--set
570	 * 各恰好一个。出错返回错误消息字符串。
571	 */
572	function parseCorrectItems(rest: string[]): { requestId: string; items: CorrectionItem[] } | string {
573	  const segments: string[][] = [[]];
574	  for (const tok of rest) {
575	    if (tok === '--item') segments.push([]);
576	    else segments[segments.length - 1].push(tok);
577	  }
578	  const headFlags = parseFlags(segments[0], ['--request']);
579	  if (typeof headFlags === 'string') return headFlags;
580	  const requestRaw = oneFlag(headFlags, '--request');
581	  if (requestRaw === null) return "'correct' 需要 --request 恰好一个";
582	  const requestId = requestRaw.trim();
583	  if (requestId === '') return '请求标识不能为空';
584	  const itemSegs = segments.slice(1);
585	  if (itemSegs.length === 0) {
586	    return "'correct' 需要至少一个 --item(--item --device <设备> --at <iso> --expect <kWh> --set <kWh>)";
587	  }
588	  const items: CorrectionItem[] = [];
589	  for (const seg of itemSegs) {
590	    const flags = parseFlags(seg, ['--device', '--at', '--expect', '--set']);
591	    if (typeof flags === 'string') return flags;
592	    const deviceRaw = oneFlag(flags, '--device');
593	    const atRaw = oneFlag(flags, '--at');
594	    const expectRaw = oneFlag(flags, '--expect');
595	    const setRaw = oneFlag(flags, '--set');
596	    if (deviceRaw === null || atRaw === null || expectRaw === null || setRaw === null) {
597	      return '每个 --item 需要 --device、--at、--expect、--set 各恰好一个';
598	    }
599	    const device = deviceRaw.trim();
600	    if (device === '') return "'--device' 的值不能为空";
601	    const ts = parseIso8601(atRaw.trim());
602	    if (ts === null) {
603	      return `选项 '--at' 的时间无效: '${atRaw.trim()}'(需秒精度 ISO8601,带 Z 或数字时区偏移)`;
604	    }
605	    const expectedMilli = parseKwh(expectRaw.trim());
606	    if (expectedMilli === null) {
607	      return `预期原读数无效: '${expectRaw.trim()}'(需非负、最多三位小数的 kWh)`;
608	    }
609	    const replacementMilli = parseKwh(setRaw.trim());
610	    if (replacementMilli === null) {
611	      return `替换读数无效: '${setRaw.trim()}'(需非负、最多三位小数的 kWh)`;
612	    }
613	    items.push({ device, ts, expectedMilli, replacementMilli });
614	  }
615	  return { requestId, items };
616	}
