628	  const targetRaw = oneFlag(flags, '--target');
629	  if (requestRaw === null || targetRaw === null) {
630	    return usageError("'undo' 需要 --request 与 --target 各恰好一个");
631	  }
632	  const requestId = requestRaw.trim();
633	  if (requestId === '') return usageError('撤销请求标识不能为空');
634	  const targetId = targetRaw.trim();
635	  if (targetId === '') return usageError('目标修正请求标识不能为空');
636	  return cmdUndo(requestId, targetId);
637	}
638	
639	function main(args: string[]): number {
640	  // 所有入口(含无参数、--help/-h、非法参数)都先取得数据目录操作权并处理
641	  // 未完成恢复,再执行查询或写入;协调失败返回 1,不输出正常业务结果。
642	  const result = withDirectoryCoordination<number>(() => runCommand(args));
643	  return typeof result === 'number' ? result : 1;
644	}
645	
646	function runCommand(args: string[]): number {
647	  if (args.length === 0) {
648	    console.log(help);
649	    return 0;
650	  }
651	  const [cmd, ...rest] = args;
652	  if (rest.length === 0 && (cmd === '--help' || cmd === '-h')) {
653	    console.log(help);
654	    return 0;
655	  }
656	
657	  if (cmd === 'import') {
658	    if (rest.length !== 1) return usageError("'import' 需要且仅需要一个 CSV 文件路径");
659	    return cmdImport(rest[0]);
660	  }
661	
662	  if (cmd === 'readings') {
663	    const parsed = parseOptions(rest);
664	    if (typeof parsed === 'string') return usageError(parsed);
665	    if (parsed.from !== undefined && parsed.to !== undefined && parsed.from >= parsed.to) {
666	      return usageError('查询起点必须早于终点(--from < --to)');
667	    }
668	    return cmdReadings(parsed);
669	  }
670	
671	  if (cmd === 'daily') {
672	    const parsed = parseOptions(rest, true, true);
673	    if (typeof parsed === 'string') return usageError(parsed);
674	    if (parsed.from === undefined || parsed.to === undefined) {
675	      return usageError("'daily' 必须同时提供 --from 与 --to(起点含、终点不含)");
676	    }
677	    if (parsed.from >= parsed.to) {
678	      return usageError('查询起点必须早于终点(--from < --to)');
679	    }
680	    if (parsed.tz !== undefined) {
681	      const bad = checkTz(parsed.tz);
682	      if (bad !== null) return usageError(bad);
683	    }
684	    return cmdDaily({
685	      devices: parsed.devices,
686	      from: parsed.from,
687	      to: parsed.to,
688	      tz: parsed.tz,
689	      maxInterval: parsed.maxInterval,
690	    });
691	  }
692	
693	  if (cmd === 'rule') return cmdRule(rest);
694	  if (cmd === 'evaluate') return cmdEvaluateEntry(rest);
695	  if (cmd === 'alerts') return cmdAlertsEntry(rest);
696	  if (cmd === 'group') return cmdGroup(rest);
697	  if (cmd === 'correct') return cmdCorrectEntry(rest);
698	  if (cmd === 'undo') return cmdUndoEntry(rest);
699	
700	  if (cmd === 'corrections') {
701	    if (rest.length !== 0) return usageError("'corrections' 不接受参数");
702	    return cmdCorrections();
703	  }
704	
705	  if (cmd === 'ack') {
706	    if (rest.length !== 1) return usageError("'ack' 需要且仅需要一个告警标识");
707	    const alertId = rest[0].trim();
708	    if (alertId === '') return usageError('告警标识不能为空');
709	    return cmdAck(alertId);
710	  }
711	
712	  if (cmd === 'backup') {
713	    if (rest.length !== 1) return usageError("'backup' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
714	    return cmdBackup(rest[0]);
715	  }
716	
717	  if (cmd === 'restore') {
718	    if (rest.length !== 1) return usageError("'restore' 需要且仅需要一个快照文件路径(须位于数据目录之外)");
719	    return cmdRestore(rest[0]);
720	  }
721	
722	  return usageError(`无法识别的参数 '${cmd}'`);
723	}
724	
725	process.exitCode = main(process.argv.slice(2));
