1	// group 子命令:分组成员版本配置、成员历史查询与分组能耗日报。
2	//
3	// - 分组以首次配置建立,标识非空唯一(去首尾空白、区分大小写);每次配置指定
4	//   生效时刻(含)与一整套已有设备,从该时刻起生效直到下一版本接替;允许乱序
5	//   补录历史版本。成员不能为空,同设备重复列出只算一次,成员顺序不影响等价性,
6	//   设备可属于多个分组。同组同一实际生效时刻、同成员集合重试成功且不新增,
7	//   异成员集合报冲突。
8	// - 配置整次成功或不提交:未知设备、冲突、损坏或不可读存储及写入失败都明确
9	//   报错并保留操作前状态。配置不改读数、规则和告警,导入也不改配置。
10	// - 日报按当地自然日切分(起点含、终点不含,首尾只统计重叠部分;默认 UTC,
11	//   可用 --tz 指定 IANA 时区,时区只决定分日),按当时生效成员计算,不把
12	//   最新成员套用到历史;首个版本生效前记为未知。各设备使用完整已存时序,
13	//   区间两端读数即使在查询范围外也参与;成员切换不需要恰好有读数,首条
14	//   读数之前、末条之后及孤立读数时段为未知,不外推。
15	// - 每个时段只有全部生效成员均处于非下降读数区间时才是有效覆盖,并计入成员
16	//   消耗之和;任一成员下降则为异常覆盖,否则任一成员未知则为未知覆盖。异常与
17	//   未知时段不计任何成员消耗,不以缺失设备为零补齐。覆盖秒数按分组实际时间
18	//   计算,不累加成员秒数。各设备片段仍以原读数区间起点累计比例向下取整,
19	//   两端累计量之差为消耗;日界线、查询边界与成员切换均不重置分摊起点,
20	//   拆开查询相加结果一致。全程 BigInt 精确计算,kWh 固定三位小数。
21	// - 可选的最大采样间隔限制(正整数秒):成员的非下降相邻区间实际时间差超过
22	//   限制时该成员在该区间记为未知(整个区间,不因查询范围、日界线或成员切换
23	//   裁短;等于限制仍可信),下降区间即使超过限制仍为异常。分组的过长间隔
24	//   未知秒数只在最终未知时段内按实际时间计并集,不叠加成员秒数。
25	// - 日报与历史只读;读取读数时拒绝同设备同一实际时刻的多条存储记录。
26	
27	import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
28	import { dirname } from 'node:path';
29	import { dataFilePath, groupFilePath, loadStore, StoreError, type Reading } from './store.ts';
30	import { formatIsoUtc } from './time.ts';
31	import { localDays, loadTimezone } from './tz.ts';
32	import { formatKwh } from './value.ts';
33	import {
34	  formatGapLine,
35	  maxIntervalText,
36	  mergeGaps,
37	  type GapDetail,
38	} from './report.ts';
39	
40	export interface GroupVersion {
41	  /** 生效时刻(含),epoch 秒。 */
42	  at: number;
43	  /** 成员设备标识,已去重并按字典序排序(规范形,成员顺序不影响等价性)。 */
44	  members: string[];
45	}
46	
47	export interface Group {
48	  /** 分组标识(非空、唯一,已去首尾空白,区分大小写)。 */
49	  id: string;
50	  /** 成员版本,按生效时刻升序。 */
51	  versions: GroupVersion[];
52	}
53	
54	function err(message: string): void {
55	  console.error(`meterwatch: ${message}`);
56	}
57	
58	/**
59	 * 解析分组存储的 JSON 结构。结构非法抛出 StoreError;source 用于错误消息
60	 * (如 `storage file <path>`)。
61	 */
62	export function parseGroups(data: unknown, source: string): Group[] {
63	  const bad = (what: string): StoreError =>
64	    new StoreError(`${source} is corrupted (${what})`);
65	  const o = data as Record<string, unknown>;
66	  if (o === null || typeof o !== 'object') throw bad('not an object');
67	  if (!Array.isArray(o.groups)) throw bad('missing groups array');
68	
69	  const ids = new Set<string>();
70	  const groups: Group[] = [];
71	  for (const g of o.groups as Array<Record<string, unknown>>) {
72	    const ok =
73	      g !== null &&
74	      typeof g === 'object' &&
75	      typeof g.id === 'string' &&
76	      g.id.length > 0 &&
77	      Array.isArray(g.versions) &&
78	      g.versions.length > 0;
79	    if (!ok) throw bad('invalid group entry');
80	    if (ids.has(g.id as string)) throw bad(`duplicate group id '${g.id}'`);
81	    ids.add(g.id as string);
82	
83	    const versions: GroupVersion[] = [];
84	    const seenAts = new Set<number>();
85	    for (const v of g.versions as Array<Record<string, unknown>>) {
86	      const vok =
87	        v !== null &&
88	        typeof v === 'object' &&
89	        Number.isSafeInteger(v.at) &&
90	        Array.isArray(v.members) &&
91	        v.members.length > 0 &&
92	        (v.members as unknown[]).every((m) => typeof m === 'string' && (m as string).length > 0);
93	      if (!vok) throw bad(`invalid version entry in group '${g.id}'`);
94	      const at = v.at as number;
95	      if (seenAts.has(at)) throw bad(`duplicate version time in group '${g.id}'`);
96	      seenAts.add(at);
97	      const members = [...(v.members as string[])].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
98	      for (let i = 1; i < members.length; i++) {
99	        if (members[i] === members[i - 1]) {
100	          throw bad(`duplicate member '${members[i]}' in group '${g.id}'`);
101	        }
102	      }
103	      versions.push({ at, members });
104	    }
105	    versions.sort((a, b) => a.at - b.at);
106	    groups.push({ id: g.id as string, versions });
107	  }
108	  return groups;
109	}
