// 推算日界线:夏令时前拨跳过的当天更短(跳过的小时不存在,不补为未知),
// 回拨当天更长(重复小时按各自实际时刻完整计入);同一当地日期在不连续
// 时段出现时合并统计、时段分别保留;整日被跳过的当地日期没有实际时段,
// 不生成虚构日报。

import { formatIsoUtc, parseUtcDate } from './time.ts';

export interface LocalDayPeriod {
  /** 时段起点(含),epoch 秒。 */
  start: number;
  /** 时段终点(不含),epoch 秒。 */
  end: number;
}

export interface LocalDay {
  /** 当地日期标签,YYYY-MM-DD。 */
  label: string;
  /** 该当地日期在查询范围内的实际 UTC 时段,按时间升序、互不重叠。 */
  periods: LocalDayPeriod[];
}

interface WallClock {
  /** 日期比较键,y*10000+m*100+d。 */
  key: number;
  /** 日期标签,YYYY-MM-DD。 */
  label: string;
  /** 墙钟分量按 UTC 解释的 epoch 秒(用于偏移与午夜推算)。 */
  naive: number;
  /** 下一个当地午夜的墙钟,按 UTC 解释的 epoch 秒。 */
  nextMidnight: number;
}

/** 校验 IANA 时区名并构造墙钟格式化器;运行环境不支持时返回 null。 */
export function loadTimezone(name: string): Intl.DateTimeFormat | null {
  if (name === '') return null;
  try {
    const fmt = new Intl.DateTimeFormat('en-US', {
      timeZone: name,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hourCycle: 'h23',
    });
    fmt.format(0);
    return fmt;
  } catch {
    return null;
  }
}

/**
 * 把时区名解析为运行环境解析后的规范 IANA 名称(如 US/Eastern 解析为
 * America/New_York);运行环境不支持时返回 null。同一实际时区的不同写法
 * 解析为同一规范名,规则时区按规范名存储与比较。
 */
export function canonicalTimezone(name: string): string | null {
  const fmt = loadTimezone(name);
  if (fmt === null) return null;
  const resolved = fmt.resolvedOptions().timeZone;
  return typeof resolved === 'string' && resolved !== '' ? resolved : null;
}

/** 年月日时分秒按 UTC 解释的 epoch 秒(setUTCFullYear 以支持 0-99 年)。 */
function naiveEpoch(y: number, mo: number, d: number, h: number, mi: number, s: number): number {
  const dt = new Date(0);
  dt.setUTCFullYear(y, mo - 1, d);
  dt.setUTCHours(h, mi, s, 0);
  return dt.getTime() / 1000;
}

/** 时刻 t 在时区 fmt 下的墙钟。 */
function wallClock(fmt: Intl.DateTimeFormat, t: number): WallClock {
  let y = 0;
  let mo = 0;
  let d = 0;
  let h = 0;
  let mi = 0;
  let s = 0;
  for (const p of fmt.formatToParts(t * 1000)) {
    switch (p.type) {
      case 'year':
        y = Number(p.value);
        break;
      case 'month':
        mo = Number(p.value);
        break;
      case 'day':
        d = Number(p.value);
        break;
      case 'hour':
        h = Number(p.value);
        break;
      case 'minute':
        mi = Number(p.value);
        break;
      case 'second':
        s = Number(p.value);
        break;
    }
  }
  const pad = (n: number): string => String(n).padStart(2, '0');
  return {
    key: y * 10000 + mo * 100 + d,
    label: `${String(y).padStart(4, '0')}-${pad(mo)}-${pad(d)}`,
    naive: naiveEpoch(y, mo, d, h, mi, s),
    nextMidnight: naiveEpoch(y, mo, d, 0, 0, 0) + 86400,
  };
}

/** 时区在时刻 t 的偏移(墙钟 - UTC),秒。 */
function offsetAt(fmt: Intl.DateTimeFormat, t: number): number {
  return wallClock(fmt, t).naive - t;
}

/** 时区在时刻 t 的偏移(墙钟 - UTC),秒;供时间表墙钟分类等外部口径使用。 */
export function offsetSecondsAt(fmt: Intl.DateTimeFormat, t: number): number {
  return offsetAt(fmt, t);
}

/**
 * 在 (t, limit] 内找第一个偏移与 o0 不同的时刻;没有返回 Infinity。
 * 先按小时步进定位再秒级二分;IANA 时区的相邻偏移切换间隔远大于一小时,
 * 一小时内两次切换且净偏移不变的情形不存在。
 */
function nextTransition(fmt: Intl.DateTimeFormat, t: number, o0: number, limit: number): number {
  let lo = t;
  let u = t;
  while (u < limit) {
    u = Math.min(u + 3600, limit);
    if (offsetAt(fmt, u) !== o0) {
      let hi = u;
      while (hi - lo > 1) {
        const mid = Math.floor((lo + hi) / 2);
        if (offsetAt(fmt, mid) !== o0) hi = mid;
        else lo = mid;
      }
      return hi;
    }
    lo = u;
  }
  return Infinity;
}

/**
 * 把 [from, to) 按当地自然日切分。返回按首次出现排序(即日期升序)的
 * 当地日期,每个日期带实际统计的 UTC 时段;同一日期的不连续时段合并到
 * 同一日期下分别列出,相邻时段并为一个区间。没有实际时段的当地日期
 * (如整体被跳过的日期)不出现。
 */
export function localDays(fmt: Intl.DateTimeFormat, from: number, to: number): LocalDay[] {
  const days: LocalDay[] = [];
  const byKey = new Map<number, LocalDay>();
  let cursor = from;
  while (cursor < to) {
    const w = wallClock(fmt, cursor);
    const o0 = w.naive - cursor;
    // 偏移不变时下一次日期变化的 UTC 时刻;wall(cursor) < nextMidnight,
    // 故 uStar > cursor 恒成立。
    const uStar = w.nextMidnight - o0;
    // 偏移切换可能先于午夜到达(如午夜前后切换夏令时),此时日期是否变化
    // 由下一轮以新偏移重新计算;段内偏移恒定,日期不会中途改变。
    const trans = nextTransition(fmt, cursor, o0, Math.min(uStar, to));
    const end = Math.min(uStar, trans, to);
    let day = byKey.get(w.key);
    if (!day) {
      day = { label: w.label, periods: [] };
      byKey.set(w.key, day);
      days.push(day);
    }
    const last = day.periods[day.periods.length - 1];
    if (last && last.end === cursor) last.end = end;
    else day.periods.push({ start: cursor, end });
    cursor = end;
  }
  return days;
}

export interface LocalDateEntry {
  /** 当地日期标签,YYYY-MM-DD,按当地日期升序。 */
  label: string;
  /** 归属该日期的全部实际 UTC 时段;null 表示整日被跳过(无实际时段)。 */
  day: LocalDay | null;
}

/**
 * 把连续日历日期范围 [fromLabel, toLabel)(YYYY-MM-DD,起日含、止日不含)映射为
 * 各当地日期在 fmt 时区下的实际 UTC 时段。每个日期统计归属该日期的全部实际
 * 时段,不把当地午夜简单套用固定偏移:夏令时短日的实际时段更短,回拨日更长,
 * 日期回退产生的不连续时段合并在同一日期下;整日被跳过的日期 day 为 null,
 * 由调用方标明跳过。日历日期本身按格里历逐日递增,与时区无关。
 */
export function localDateRange(
  fmt: Intl.DateTimeFormat,
  fromLabel: string,
  toLabel: string,
): LocalDateEntry[] {
  const fromUtc = parseUtcDate(fromLabel) as number;
  const toUtc = parseUtcDate(toLabel) as number;
  // 任一日期的当地午夜与 UTC 午夜之差不超过该时区的最大偏移(远小于两天),
  // 向两侧放宽后再切分,保证首尾日期的实际时段完整落入切分范围。
  const margin = 2 * 86400;
  const days = localDays(fmt, fromUtc - margin, toUtc + margin);
  const byLabel = new Map<string, LocalDay>();
  for (const d of days) byLabel.set(d.label, d);
  const out: LocalDateEntry[] = [];
  for (let t = fromUtc; t < toUtc; t += 86400) {
    const label = formatIsoUtc(t).slice(0, 10);
    out.push({ label, day: byLabel.get(label) ?? null });
  }
  return out;
}

// group schedule-report 子命令:按本地每周运行时间表把查询范围划分为运行与
// 非运行两类时段,分别核查分组能耗的只读报表,用于核查停运消耗。
//
// - 时间表为零个或多个每周窗口:开始星期 + 起止 HH:mm。开始限 00:00-23:59,
//   结束另可 24:00;同值起止拒绝;结束早于开始即跨至下一日(尾段沿用开始
//   日规则,周日可跨至周一)。窗口起点含、终点不含,重叠或重复取并集;空表
//   (零个窗口)表示全部非运行。
// - 分类按实际时刻的当地日期与墙钟:每秒只属一类;夏令时跳过时段不虚构
//   覆盖,回拨重复时段各自分类,不套固定偏移或日长。--tz 只解释时间表,
//   不重新解释起止时刻或已存读数。
// - 能耗口径与 group daily 相同:按当时生效成员与完整读数时序,全部成员
//   可信才累加消耗,任一成员下降优先为异常,否则任一成员未知为未知;首个
//   版本生效前、读数首末之外与孤立读数未知,不外推。采样限制按原始相邻
//   区间判断,裁切不使过长区间可信,等于限制仍可信;有效片段取原区间起点
//   累计比例向下取整的两端差,切分不重置起点;BigInt 精确计算,kWh 固定
//   三位小数。
// - 两类覆盖合计等于查询时长,消耗合计等于同范围、同限制的分组日报,拆开
//   查询相加一致;覆盖按时间计,不叠加成员秒数。
// - 只读:不改写时间表或业务存储,不自动评估;修正撤销后重查使用当前读数。
//   成功(含不可计算结果)返回 0;非法时间表返回 2;时间表文件不可读、未知
//   分组、所用存储损坏或全库重复读数身份返回 1,指出原因,不输出部分报表。

import { readFileSync } from 'node:fs';
import { dataFilePath, groupFilePath, loadStore, StoreError, type Reading } from './store.ts';
import { formatIsoUtc, parseUtcDate } from './time.ts';
import { localDays, loadTimezone, offsetSecondsAt } from './tz.ts';
import { formatKwh } from './value.ts';
import { formatGapLine, maxIntervalText, mergeGaps, type GapDetail } from './report.ts';
import {
  computeGroupSegment,
  loadCheckedSeriesByDevice,
  loadGroups,
  type Group,
} from './groups.ts';

function err(message: string): void {
  console.error(`meterwatch: ${message}`);
}

export interface ScheduleWindow {
  /** 开始星期,0=周日 .. 6=周六。 */
  startDow: number;
  /** 开始当日的起始分钟,0..1439。 */
  startMin: number;
  /** 相对开始日的结束分钟(不含),恒大于 startMin;结束早于开始时 +1440 跨至下一日。 */
  endMin: number;
}

const DOW_BY_NAME: Record<string, number> = {
  sun: 0,
  mon: 1,
  tue: 2,
  wed: 3,
  thu: 4,
  fri: 5,
  sat: 6,
};

/** 解析 HH:mm 为当日分钟数;allow24 时另接受 24:00(=1440)。无效返回 null。 */
function parseHm(raw: string, allow24: boolean): number | null {
  const m = /^(\d{2}):(\d{2})$/.exec(raw);
  if (!m) return null;
  const h = Number(m[1]);
  const mi = Number(m[2]);
  if (mi > 59) return null;
  if (h > 23) {
    if (allow24 && h === 24 && mi === 0) return 1440;
    return null;
  }
  return h * 60 + mi;
}

/**
 * 解析每周运行时间表文本。每行一个窗口:<星期> <开始 HH:mm> <结束 HH:mm>;
 * 空行与 # 之后的注释忽略。星期为 mon..sun(不区分大小写)。开始限
 * 00:00-23:59,结束另可 24:00;同值起止拒绝;结束早于开始跨至下一日。
 * 重叠或重复窗口不在此拒绝,分类时取并集。非法时返回错误消息字符串。
 */
export function parseSchedule(text: string): ScheduleWindow[] | string {
  const windows: ScheduleWindow[] = [];
  const lines = text.split(/\r\n|\r|\n/);
  for (let i = 0; i < lines.length; i++) {
    const hash = lines[i].indexOf('#');
    const line = (hash === -1 ? lines[i] : lines[i].slice(0, hash)).trim();
    if (line === '') continue;
    const where = `line ${i + 1}`;
    const parts = line.split(/\s+/);
    if (parts.length !== 3) {
      return `${where}: expect '<weekday> <start HH:mm> <end HH:mm>' (weekday: mon..sun)`;
    }
    const dow = DOW_BY_NAME[parts[0].toLowerCase()];
    if (dow === undefined) {
      return `${where}: unknown weekday '${parts[0]}' (expect mon, tue, wed, thu, fri, sat or sun)`;
    }
    const start = parseHm(parts[1], false);
    if (start === null) {
      return `${where}: invalid start time '${parts[1]}' (expect HH:mm within 00:00-23:59)`;
    }
    const end = parseHm(parts[2], true);
    if (end === null) {
      return `${where}: invalid end time '${parts[2]}' (expect HH:mm within 00:00-24:00)`;
    }
    if (end === start) {
      return `${where}: start and end must differ (both are '${parts[1]}')`;
    }
    // 结束早于开始即跨至下一日,尾段沿用开始日规则(周日可跨至周一)。
    const endMin = end < start ? end + 1440 : end;
    windows.push({ startDow: dow, startMin: start, endMin });
  }
  return windows;
}

interface Period {
  /** 时段起点(含),epoch 秒。 */
  start: number;
  /** 时段终点(不含),epoch 秒。 */
  end: number;
}

/** 墙钟午夜(按 UTC 解释的 epoch 秒)对应的星期,0=周日。1970-01-01 为周四。 */
function dowOfNaive(naiveMidnight: number): number {
  const days = Math.floor(naiveMidnight / 86400);
  return (((days + 4) % 7) + 7) % 7;
}

/**
 * 把 [from, to) 按每周时间表分为运行与非运行两类实际 UTC 时段,两类合计
 * 恰好等于查询范围(每秒只属一类)。分类按实际时刻的当地日期与墙钟:
 * 当地日切分自命名时区(段内偏移恒定),窗口墙钟区间与当日墙钟区间求交
 * 后换算回 UTC;夏令时跳过的墙钟没有实际时刻,不虚构覆盖,回拨重复的
 * 墙钟两段实际时段各自分类,不套固定偏移或日长。
 */
export function classifyPeriods(
  fmt: Intl.DateTimeFormat,
  from: number,
  to: number,
  windows: ScheduleWindow[],
): { running: Period[]; nonRunning: Period[] } {
  const raw: Period[] = [];
  if (windows.length > 0) {
    for (const day of localDays(fmt, from, to)) {
      const dayNaive = parseUtcDate(day.label) as number;
      // 本日开始的窗口,以及上一日开始、跨至本日的窗口尾段。
      const wall: Array<[number, number]> = [];
      for (const w of windows) {
        for (const startNaive of [dayNaive, dayNaive - 86400]) {
          if (dowOfNaive(startNaive) !== w.startDow) continue;
          wall.push([startNaive + w.startMin * 60, startNaive + w.endMin * 60]);
        }
      }
      if (wall.length === 0) continue;
      for (const p of day.periods) {
        // localDays 的时段内偏移恒定,墙钟区间随 UTC 线性平移。
        const off = offsetSecondsAt(fmt, p.start);
        const ws = p.start + off;
        const we = p.end + off;
        for (const [a, b] of wall) {
          const lo = Math.max(a, ws);
          const hi = Math.min(b, we);
          if (lo < hi) raw.push({ start: lo - off, end: hi - off });
        }
      }
    }
    raw.sort((a, b) => a.start - b.start);
  }
  // 重叠或重复窗口取并集。
  const running: Period[] = [];
  for (const r of raw) {
    const last = running[running.length - 1];
    if (last && r.start <= last.end) {
      if (r.end > last.end) last.end = r.end;
    } else {
      running.push({ start: r.start, end: r.end });
    }
  }
  const nonRunning: Period[] = [];
  let cursor = from;
  for (const r of running) {
    if (cursor < r.start) nonRunning.push({ start: cursor, end: r.start });
    cursor = r.end;
  }
  if (cursor < to) nonRunning.push({ start: cursor, end: to });
  return { running, nonRunning };
}

/**
 * 分组运行/非运行时段能耗报表:按本地每周运行时间表把 [from, to) 分为
 * 两类时段,分别按当时生效成员核查能耗。只读,不写入数据。返回进程退出码。
 */
export function cmdGroupScheduleReport(opts: {
  id: string;
  /** 本地每周运行时间表文件路径(只读)。 */
  schedulePath: string;
  from: number;
  to: number;
  /** 解释时间表的 IANA 时区;省略为 UTC。 */
  tz?: string;
  /** 最大采样间隔限制(正整数秒);省略表示无上限。只影响本次查询结果。 */
  maxInterval?: number;
}): number {
  const tzName = opts.tz ?? 'UTC';
  const tz = loadTimezone(tzName);
  if (!tz) {
    err(`unknown timezone '${tzName}' (expect an IANA timezone name supported by this runtime)`);
    return 2;
  }

  let text: string;
  try {
    text = readFileSync(opts.schedulePath, 'utf8');
  } catch (e) {
    err(`cannot read schedule file ${opts.schedulePath}: ${(e as Error).message}`);
    return 1;
  }
  const parsed = parseSchedule(text);
  if (typeof parsed === 'string') {
    err(`invalid schedule file ${opts.schedulePath}: ${parsed}`);
    return 2;
  }
  const windows = parsed;

  let groups: Group[];
  try {
    groups = loadGroups(groupFilePath());
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  const group = groups.find((g) => g.id === opts.id);
  if (!group) {
    err(`unknown group '${opts.id}'`);
    return 1;
  }

  let seriesByDevice: Map<string, Reading[]>;
  try {
    seriesByDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  const { running, nonRunning } = classifyPeriods(tz, opts.from, opts.to, windows);

  console.log(`group: ${group.id}`);
  console.log(`schedule: ${opts.schedulePath} (${windows.length} window(s))`);
  console.log(`timezone: ${tzName}`);
  console.log(`max-interval: ${maxIntervalText(opts.maxInterval)}`);

  const classes: Array<{ name: string; periods: Period[] }> = [
    { name: 'running', periods: running },
    { name: 'non-running', periods: nonRunning },
  ];
  let incomplete = false;
  const coverage: number[] = [];
  for (const c of classes) {
    let valid = 0;
    let anomaly = 0;
    let unknown = 0;
    let gapUnknown = 0;
    const gaps: GapDetail[] = [];
    let consumption = 0n;
    for (const p of c.periods) {
      const stats = computeGroupSegment(
        group.versions,
        seriesByDevice,
        p.start,
        p.end,
        opts.maxInterval,
      );
      valid += stats.valid;
      anomaly += stats.anomaly;
      unknown += stats.unknown;
      gapUnknown += stats.gapUnknown;
      mergeGaps(gaps, stats.gaps);
      consumption += stats.consumption;
    }
    let seconds = 0;
    for (const p of c.periods) seconds += p.end - p.start;
    coverage.push(seconds);
    const classIncomplete = anomaly > 0 || unknown > 0;
    if (classIncomplete) incomplete = true;

    const consumptionText =
      valid > 0
        ? `consumption=${formatKwh(consumption)} kWh (estimate)`
        : 'consumption=n/a (no valid coverage)';
    let line =
      `  class=${c.name}  ${consumptionText}` +
      `  valid=${valid}s  anomaly=${anomaly}s  unknown=${unknown}s`;
    if (opts.maxInterval !== undefined) line += `  gap=${gapUnknown}s`;
    if (classIncomplete) line += '  INCOMPLETE';
    console.log(line);
    for (const p of c.periods) {
      console.log(`    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
    }
    for (const g of gaps) {
      console.log(formatGapLine(g));
    }
  }

  const status = incomplete
    ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
    : 'status=complete';
  console.log(
    `  summary: group=${group.id}  running=${coverage[0]}s  non-running=${coverage[1]}s` +
      `  total=${opts.to - opts.from}s  ${status}`,
  );
  return 0;
}

// group schedule-report 子命令:按本地每周运行时间表把查询范围划分为运行与
// 非运行两类时段,分别核查分组能耗的只读报表,用于核查停运消耗。
//
// - 时间表为零个或多个每周窗口:开始星期 + 起止 HH:mm。开始限 00:00-23:59,
//   结束另可 24:00;同值起止拒绝;结束早于开始即跨至下一日(尾段沿用开始
//   日规则,周日可跨至周一)。窗口起点含、终点不含,重叠或重复取并集;空表
//   (零个窗口)表示全部非运行。
// - 分类按实际时刻的当地日期与墙钟:每秒只属一类;夏令时跳过时段不虚构
//   覆盖,回拨重复时段各自分类,不套固定偏移或日长。--tz 只解释时间表,
//   不重新解释起止时刻或已存读数。
// - 能耗口径与 group daily 相同:按当时生效成员与完整读数时序,全部成员
//   可信才累加消耗,任一成员下降优先为异常,否则任一成员未知为未知;首个
//   版本生效前、读数首末之外与孤立读数未知,不外推。采样限制按原始相邻
//   区间判断,裁切不使过长区间可信,等于限制仍可信;有效片段取原区间起点
//   累计比例向下取整的两端差,切分不重置起点;BigInt 精确计算,kWh 固定
//   三位小数。
// - 两类覆盖合计等于查询时长,消耗合计等于同范围、同限制的分组日报,拆开
//   查询相加一致;覆盖按时间计,不叠加成员秒数。
// - 只读:不改写时间表或业务存储,不自动评估;修正撤销后重查使用当前读数。
//   成功(含不可计算结果)返回 0;非法时间表返回 2;时间表文件不可读、未知
//   分组、所用存储损坏或全库重复读数身份返回 1,指出原因,不输出部分报表。

import { readFileSync } from 'node:fs';
import { dataFilePath, groupFilePath, loadStore, StoreError, type Reading } from './store.ts';
import { formatIsoUtc, parseUtcDate } from './time.ts';
import { localDays, loadTimezone, wallSegments } from './tz.ts';
import { formatKwh } from './value.ts';
import { formatGapLine, maxIntervalText, mergeGaps, type GapDetail } from './report.ts';
import {
  computeGroupSegment,
  loadCheckedSeriesByDevice,
  loadGroups,
  type Group,
} from './groups.ts';

function err(message: string): void {
  console.error(`meterwatch: ${message}`);
}

export interface ScheduleWindow {
  /** 开始星期,0=周日 .. 6=周六。 */
  startDow: number;
  /** 开始当日的起始分钟,0..1439。 */
  startMin: number;
  /** 相对开始日的结束分钟(不含),恒大于 startMin;结束早于开始时 +1440 跨至下一日。 */
  endMin: number;
}

const DOW_BY_NAME: Record<string, number> = {
  sun: 0,
  mon: 1,
  tue: 2,
  wed: 3,
  thu: 4,
  fri: 5,
  sat: 6,
};

/** 解析 HH:mm 为当日分钟数;allow24 时另接受 24:00(=1440)。无效返回 null。 */
function parseHm(raw: string, allow24: boolean): number | null {
  const m = /^(\d{2}):(\d{2})$/.exec(raw);
  if (!m) return null;
  const h = Number(m[1]);
  const mi = Number(m[2]);
  if (mi > 59) return null;
  if (h > 23) {
    if (allow24 && h === 24 && mi === 0) return 1440;
    return null;
  }
  return h * 60 + mi;
}

/**
 * 解析每周运行时间表文本。每行一个窗口:<星期> <开始 HH:mm> <结束 HH:mm>;
 * 空行与 # 之后的注释忽略。星期为 mon..sun(不区分大小写)。开始限
 * 00:00-23:59,结束另可 24:00;同值起止拒绝;结束早于开始跨至下一日。
 * 重叠或重复窗口不在此拒绝,分类时取并集。非法时返回错误消息字符串。
 */
export function parseSchedule(text: string): ScheduleWindow[] | string {
  const windows: ScheduleWindow[] = [];
  const lines = text.split(/\r\n|\r|\n/);
  for (let i = 0; i < lines.length; i++) {
    const hash = lines[i].indexOf('#');
    const line = (hash === -1 ? lines[i] : lines[i].slice(0, hash)).trim();
    if (line === '') continue;
    const where = `line ${i + 1}`;
    const parts = line.split(/\s+/);
    if (parts.length !== 3) {
      return `${where}: expect '<weekday> <start HH:mm> <end HH:mm>' (weekday: mon..sun)`;
    }
    const dow = DOW_BY_NAME[parts[0].toLowerCase()];
    if (dow === undefined) {
      return `${where}: unknown weekday '${parts[0]}' (expect mon, tue, wed, thu, fri, sat or sun)`;
    }
    const start = parseHm(parts[1], false);
    if (start === null) {
      return `${where}: invalid start time '${parts[1]}' (expect HH:mm within 00:00-23:59)`;
    }
    const end = parseHm(parts[2], true);
    if (end === null) {
      return `${where}: invalid end time '${parts[2]}' (expect HH:mm within 00:00-24:00)`;
    }
    if (end === start) {
      return `${where}: start and end must differ (both are '${parts[1]}')`;
    }
    // 结束早于开始即跨至下一日,尾段沿用开始日规则(周日可跨至周一)。
    const endMin = end < start ? end + 1440 : end;
    windows.push({ startDow: dow, startMin: start, endMin });
  }
  return windows;
}

interface Period {
  /** 时段起点(含),epoch 秒。 */
  start: number;
  /** 时段终点(不含),epoch 秒。 */
  end: number;
}

/** 墙钟午夜(按 UTC 解释的 epoch 秒)对应的星期,0=周日。1970-01-01 为周四。 */
function dowOfNaive(naiveMidnight: number): number {
  const days = Math.floor(naiveMidnight / 86400);
  return (((days + 4) % 7) + 7) % 7;
}

/**
 * 把 [from, to) 按每周时间表分为运行与非运行两类实际 UTC 时段,两类合计
 * 恰好等于查询范围(每秒只属一类)。分类按实际时刻的当地日期与墙钟:
 * 当地日切分自命名时区(段内偏移恒定),窗口墙钟区间与当日墙钟区间求交
 * 后换算回 UTC;夏令时跳过的墙钟没有实际时刻,不虚构覆盖,回拨重复的
 * 墙钟两段实际时段各自分类,不套固定偏移或日长。
 */
export function classifyPeriods(
  fmt: Intl.DateTimeFormat,
  from: number,
  to: number,
  windows: ScheduleWindow[],
): { running: Period[]; nonRunning: Period[] } {
  const raw: Period[] = [];
  if (windows.length > 0) {
    for (const day of localDays(fmt, from, to)) {
      const dayNaive = parseUtcDate(day.label) as number;
      // 本日开始的窗口,以及上一日开始、跨至本日的窗口尾段。
      const wall: Array<[number, number]> = [];
      for (const w of windows) {
        for (const startNaive of [dayNaive, dayNaive - 86400]) {
          if (dowOfNaive(startNaive) !== w.startDow) continue;
          wall.push([startNaive + w.startMin * 60, startNaive + w.endMin * 60]);
        }
      }
      if (wall.length === 0) continue;
      for (const p of day.periods) {
        // localDays 的时段内偏移恒定,墙钟区间随 UTC 线性平移。
        const off = offsetSecondsAt(fmt, p.start);
        const ws = p.start + off;
        const we = p.end + off;
        for (const [a, b] of wall) {
          const lo = Math.max(a, ws);
          const hi = Math.min(b, we);
          if (lo < hi) raw.push({ start: lo - off, end: hi - off });
        }
      }
    }
    raw.sort((a, b) => a.start - b.start);
  }
  // 重叠或重复窗口取并集。
  const running: Period[] = [];
  for (const r of raw) {
    const last = running[running.length - 1];
    if (last && r.start <= last.end) {
      if (r.end > last.end) last.end = r.end;
    } else {
      running.push({ start: r.start, end: r.end });
    }
  }
  const nonRunning: Period[] = [];
  let cursor = from;
  for (const r of running) {
    if (cursor < r.start) nonRunning.push({ start: cursor, end: r.start });
    cursor = r.end;
  }
  if (cursor < to) nonRunning.push({ start: cursor, end: to });
  return { running, nonRunning };
}

/**
 * 分组运行/非运行时段能耗报表:按本地每周运行时间表把 [from, to) 分为
 * 两类时段,分别按当时生效成员核查能耗。只读,不写入数据。返回进程退出码。
 */
export function cmdGroupScheduleReport(opts: {
  id: string;
  /** 本地每周运行时间表文件路径(只读)。 */
  schedulePath: string;
  from: number;
  to: number;
  /** 解释时间表的 IANA 时区;省略为 UTC。 */
  tz?: string;
  /** 最大采样间隔限制(正整数秒);省略表示无上限。只影响本次查询结果。 */
  maxInterval?: number;
}): number {
  const tzName = opts.tz ?? 'UTC';
  const tz = loadTimezone(tzName);
  if (!tz) {
    err(`unknown timezone '${tzName}' (expect an IANA timezone name supported by this runtime)`);
    return 2;
  }

  let text: string;
  try {
    text = readFileSync(opts.schedulePath, 'utf8');
  } catch (e) {
    err(`cannot read schedule file ${opts.schedulePath}: ${(e as Error).message}`);
    return 1;
  }
  const parsed = parseSchedule(text);
  if (typeof parsed === 'string') {
    err(`invalid schedule file ${opts.schedulePath}: ${parsed}`);
    return 2;
  }
  const windows = parsed;

  let groups: Group[];
  try {
    groups = loadGroups(groupFilePath());
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }
  const group = groups.find((g) => g.id === opts.id);
  if (!group) {
    err(`unknown group '${opts.id}'`);
    return 1;
  }

  let seriesByDevice: Map<string, Reading[]>;
  try {
    seriesByDevice = loadCheckedSeriesByDevice(loadStore(dataFilePath()));
  } catch (e) {
    if (e instanceof StoreError) {
      err(e.message);
      return 1;
    }
    throw e;
  }

  const { running, nonRunning } = classifyPeriods(tz, opts.from, opts.to, windows);

  console.log(`group: ${group.id}`);
  console.log(`schedule: ${opts.schedulePath} (${windows.length} window(s))`);
  console.log(`timezone: ${tzName}`);
  console.log(`max-interval: ${maxIntervalText(opts.maxInterval)}`);

  const classes: Array<{ name: string; periods: Period[] }> = [
    { name: 'running', periods: running },
    { name: 'non-running', periods: nonRunning },
  ];
  let incomplete = false;
  const coverage: number[] = [];
  for (const c of classes) {
    let valid = 0;
    let anomaly = 0;
    let unknown = 0;
    let gapUnknown = 0;
    const gaps: GapDetail[] = [];
    let consumption = 0n;
    for (const p of c.periods) {
      const stats = computeGroupSegment(
        group.versions,
        seriesByDevice,
        p.start,
        p.end,
        opts.maxInterval,
      );
      valid += stats.valid;
      anomaly += stats.anomaly;
      unknown += stats.unknown;
      gapUnknown += stats.gapUnknown;
      mergeGaps(gaps, stats.gaps);
      consumption += stats.consumption;
    }
    let seconds = 0;
    for (const p of c.periods) seconds += p.end - p.start;
    coverage.push(seconds);
    const classIncomplete = anomaly > 0 || unknown > 0;
    if (classIncomplete) incomplete = true;

    const consumptionText =
      valid > 0
        ? `consumption=${formatKwh(consumption)} kWh (estimate)`
        : 'consumption=n/a (no valid coverage)';
    let line =
      `  class=${c.name}  ${consumptionText}` +
      `  valid=${valid}s  anomaly=${anomaly}s  unknown=${unknown}s`;
    if (opts.maxInterval !== undefined) line += `  gap=${gapUnknown}s`;
    if (classIncomplete) line += '  INCOMPLETE';
    console.log(line);
    for (const p of c.periods) {
      console.log(`    period=${formatIsoUtc(p.start)}..${formatIsoUtc(p.end)}`);
    }
    for (const g of gaps) {
      console.log(formatGapLine(g));
    }
  }

  const status = incomplete
    ? 'status=INCOMPLETE (unknown or anomaly coverage present)'
    : 'status=complete';
  console.log(
    `  summary: group=${group.id}  running=${coverage[0]}s  non-running=${coverage[1]}s` +
      `  total=${opts.to - opts.from}s  ${status}`,
  );
  return 0;
}

